'use client';

import { useState } from 'react';
import axios from 'axios';

export default function ObjectGenerator() {
  const [formData, setFormData] = useState({ name: '', members: '' });
  const [generatedScript, setGeneratedScript] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Transforma a string "Host1, Host2" num array ["Host1", "Host2"][cite: 3]
    const membersArray = formData.members.split(',').map(i => i.trim());

    try {
      const response = await axios.post(
        'http://localhost:3001/api/generate',
        { 
          type: 'address_group', // Atualize no seu backend para chamar createAddressGroup
          payload: {
            name: formData.name,
            members: membersArray
          } 
        },
        { withCredentials: true }
      );
      setGeneratedScript(response.data.script);
    } catch (error) {
      console.error('Erro ao gerar script', error);
    }
  };

  return (
    <div className="card p-4 shadow-sm mb-4">
      <h4 className="mb-3">Criar Grupo de Endereços (Address Group)</h4>
      <form onSubmit={handleSubmit}>
        <div className="row mb-3">
          <div className="col-md-6">
            <label className="form-label">Nome do Grupo (ex: GRP_SERVIDORES)</label>
            <input type="text" className="form-control" required
              onChange={e => setFormData({...formData, name: e.target.value})} />
          </div>
          <div className="col-md-6">
            <label className="form-label">Membros (separados por vírgula)</label>
            <input type="text" className="form-control" placeholder="ex: Servidor_Web, Servidor_BD" required
              onChange={e => setFormData({...formData, members: e.target.value})} />
          </div>
        </div>
        <button type="submit" className="btn btn-primary w-100">Gerar Script CLI</button>
      </form>

      {generatedScript && (
        <div className="mt-4">
          <h5>Script Gerado (Copie e cole no terminal):</h5>
          <pre className="bg-dark text-success p-3 rounded">
            <code>{generatedScript}</code>
          </pre>
          <button className="btn btn-outline-secondary btn-sm" 
            onClick={() => navigator.clipboard.writeText(generatedScript)}>
            Copiar Script
          </button>
        </div>
      )}
    </div>
  );
}